-- WARNING: Apply in a Supabase SQL editor for persistent, shared database/auth/storage.
-- Public browsing is anonymous; submissions are private until moderated. No demonstration playground records are seeded.
create extension if not exists pgcrypto;
create type public.feature_status as enum ('present','absent','partial','unavailable','unknown','na');
create type public.review_status as enum ('pending','approved','rejected');
create table public.government_agencies (id uuid primary key default gen_random_uuid(), name text not null unique, website text, contact text, created_at timestamptz not null default now());
create table public.parks (id uuid primary key default gen_random_uuid(), name text not null, address text, municipality text, county text, borough text, latitude double precision, longitude double precision, agency_id uuid references public.government_agencies(id), website text, contact text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(latitude is null or latitude between 40 and 46), check(longitude is null or longitude between -80 and -71));
create table public.playgrounds (id uuid primary key default gen_random_uuid(), park_id uuid references public.parks(id) on delete set null, name text not null, parent_park text, address text, municipality text, county text, borough text, latitude double precision, longitude double precision, agency_id uuid references public.government_agencies(id), website text, contact text, hours text, directions text, age_range text, seasonal_closures text, fees text, resident_restrictions text, fencing text, parking_distance text, restroom_distance text, known_barriers text, observed_at date, verification_status text not null default 'unverified' check(verification_status in ('unverified','community_reported','source_reviewed','verified')), source_url text, source_name text, is_public boolean not null default true, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(name,address), check(latitude is null or latitude between 40 and 46), check(longitude is null or longitude between -80 and -71));
create table public.feature_definitions (id text primary key, name text not null, category text not null, description text, active boolean not null default true);
create table public.playground_features (id uuid primary key default gen_random_uuid(), playground_id uuid not null references public.playgrounds(id) on delete cascade, feature_id text not null references public.feature_definitions(id), status public.feature_status not null default 'unknown', quantity integer check(quantity is null or quantity>=0), description text, source_url text, source_organization text, observed_at date, imported_at timestamptz, verification_method text, verification_status text not null default 'unverified', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(playground_id,feature_id));
create table public.equipment_inventories (id uuid primary key default gen_random_uuid(), playground_id uuid not null references public.playgrounds(id) on delete cascade, equipment_name text not null, quantity integer check(quantity is null or quantity>=0), condition text, description text, observed_at date, source_url text, created_at timestamptz not null default now());
create table public.accessibility_assessments (id uuid primary key default gen_random_uuid(), playground_id uuid not null references public.playgrounds(id) on delete cascade, assessor_id uuid, assessed_at date not null, physical_access jsonb not null default '{}', meaningful_play jsonb not null default '{}', communication jsonb not null default '{}', sensory_inclusion jsonb not null default '{}', supporting_facilities jsonb not null default '{}', completeness_percent numeric check(completeness_percent between 0 and 100), method text, notes text, verification_status text not null default 'unverified', created_at timestamptz not null default now());
create table public.data_sources (id uuid primary key default gen_random_uuid(), name text not null, organization text, source_url text, license text, schema_notes text, last_imported_at timestamptz, created_at timestamptz not null default now());
create table public.playground_photos (id uuid primary key default gen_random_uuid(), playground_id uuid not null references public.playgrounds(id) on delete cascade, storage_path text not null, caption text, alt_text text, source text, approved boolean not null default false, created_at timestamptz not null default now());
create table public.community_submissions (id uuid primary key default gen_random_uuid(), submission_type text not null, playground_id uuid references public.playgrounds(id) on delete set null, playground_name text, parent_park text, address text, municipality text, county text, description text, barrier_category text, observed_at date, source_url text, submitter_email text, status public.review_status not null default 'pending', submitted_by uuid, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz not null default now());
create table public.barrier_reports (id uuid primary key default gen_random_uuid(), playground_id uuid references public.playgrounds(id) on delete set null, category text, description text not null, observed_at date not null, source_submission_id uuid references public.community_submissions(id), status public.review_status not null default 'pending', created_at timestamptz not null default now());
create table public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('admin','moderator','volunteer')), created_at timestamptz not null default now());
create table public.import_history (id uuid primary key default gen_random_uuid(), source_name text not null, source_url text, started_at timestamptz not null default now(), completed_at timestamptz, imported_count integer not null default 0, skipped_count integer not null default 0, error_count integer not null default 0, status text not null default 'running', log jsonb not null default '[]');
create table public.verification_history (id uuid primary key default gen_random_uuid(), playground_id uuid references public.playgrounds(id) on delete set null, feature_observation_id uuid references public.playground_features(id) on delete set null, changed_by uuid, action text not null, before_value jsonb, after_value jsonb, note text, created_at timestamptz not null default now());
create index playgrounds_location_idx on public.playgrounds(latitude,longitude);
create index playgrounds_county_idx on public.playgrounds(county,borough);
create index features_feature_status_idx on public.playground_features(feature_id,status);
create index submissions_status_idx on public.community_submissions(status,created_at desc);

