','Communication'),('picture_boards','Picture-based communication boards','Communication'),('multilingual_boards','Multilingual communication boards','Communication'),('braille_signage','Braille signage','Communication'),('visual_instructions','Visual instructions','Communication'),('accessible_wayfinding','Accessible wayfinding','Communication'),('quiet_areas','Quiet areas','Sensory'),('sensory_panels','Sensory panels','Sensory'),('tactile_features','Tactile play features','Sensory'),('musical_equipment','Musical equipment','Sensory'),('sensory_gardens','Sensory gardens','Sensory'),('shaded_retreats','Shaded retreat spaces','Sensory'),('secure_gates','Secure gates','Sensory'),('accessible_water_play','Accessible water play','Sensory'),('low_stimulation_play','Low-stimulation play','Sensory'),('public_restrooms','Public restrooms','Facilities'),('accessible_restrooms','Wheelchair-accessible restrooms','Facilities'),('family_restrooms','Family or companion restrooms','Facilities'),('adult_changing_tables','Adult-sized changing tables','Facilities'),('baby_changing_stations','Baby-changing stations','Facilities'),('accessible_parking','Accessible parking','Facilities'),('accessible_dropoff','Accessible drop-off area','Facilities'),('accessible_transport','Accessible transportation nearby','Facilities'),('shaded_seating','Shaded seating','Facilities'),('benches_backrests','Benches with backrests and armrests','Facilities'),('drinking_fountains','Accessible drinking fountains','Facilities') on conflict(id) do nothing;

alter table public.playgrounds enable row level security;
alter table public.feature_definitions enable row level security;
alter table public.playground_features enable row level security;
alter table public.government_agencies enable row level security;
alter table public.parks enable row level security;
alter table public.equipment_inventories enable row level security;
alter table public.accessibility_assessments enable row level security;
alter table public.data_sources enable row level security;
alter table public.playground_photos enable row level security;
alter table public.community_submissions enable row level security;
alter table public.barrier_reports enable row level security;
alter table public.user_roles enable row level security;
alter table public.import_history enable row level security;
alter table public.verification_history enable row level security;
create or replace function public.has_role(allowed text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=any(allowed)) $$;
create policy "Public can view published playgrounds" on public.playgrounds for select using(is_public and not is_demo);
create policy "Admins edit playgrounds" on public.playgrounds for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view feature definitions" on public.feature_definitions for select using(active);
create policy "Public can view observations" on public.playground_features for select using(exists(select 1 from public.playgrounds p where p.id=playground_id and p.is_public and not p.is_demo));
create policy "Admins manage observations" on public.playground_features for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view agencies" on public.government_agencies for select using(true);
create policy "Admins manage agencies" on public.government_agencies for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view parks" on public.parks for select using(true);
create policy "Admins manage parks" on public.parks for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view approved photos" on public.playground_photos for select using(approved and exists(select 1 from public.playgrounds p where p.id=playground_id and p.is_public));
create policy "Admins manage photos" on public.playground_photos for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Anyone can submit community reports" on public.community_submissions for insert with check(status='pending');
create policy "Moderators view submissions" on public.community_submissions for select using(public.has_role(array['admin','moderator']));
create policy "Moderators review submissions" on public.community_submissions for update using(public.has_role(array['admin','moderator'])) with check(public.has_role(array['admin','moderator']));
create policy "Anyone can submit barrier reports" on public.barrier_reports for insert with check(status='pending');
create policy "Moderators manage barrier reports" on public.barrier_reports for all using(public.has_role(array['admin','moderator'])) with check(public.has_role(array['admin','moderator']));
create policy "Users read own role" on public.user_roles for select using(user_id=auth.uid());
create policy "Admins manage roles" on public.user_roles for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Admins manage supporting records" on public.equipment_inventories for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view assessments" on public.accessibility_assessments for select using(exists(select 1 from public.playgrounds p where p.id=playground_id and p.is_public));
create policy "Admins manage assessments" on public.accessibility_assessments for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Public can view sources" on public.data_sources for select using(true);
create policy "Admins manage sources" on public.data_sources for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Admins manage imports" on public.import_history for all using(public.has_role(array['admin'])) with check(public.has_role(array['admin']));
create policy "Admins view audit history" on public.verification_history for select using(public.has_role(array['admin','moderator']));
create policy "Admins create audit history" on public.verification_history for insert with check(public.has_role(array['admin']));

-- Keep community-provided contact data private: no public SELECT policy exists for submissions.
-- Storage bucket may be created in Supabase UI as private 'playground-photos'; approve images only after review.
